import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import ChangePasswordModal from './ChangePasswordModal';
import ScanModal from './ScanModal';

export default function Navbar({ title, sub }) {
  const { user, logout } = useAuth();
  const nav = useNavigate();
  const [showPw, setShowPw]     = useState(false);
  const [showScan, setShowScan] = useState(false);

  const doLogout = async () => { await logout(); nav('/login'); };

  return (
    <>
      <nav className="navbar">
        <div className="nb-brand">
          <img src="/logo-dashboard.png" alt="Logo" style={{ width:34, height:34, borderRadius:'50%', objectFit:'cover' }} />
          <div>
            <span className="nb-title">{title || 'QR Office'}</span>
            {sub && <span className="nb-sub">{sub}</span>}
          </div>
        </div>
        <div className="nb-actions">
          <button className="btn btn-ghost btn-sm" onClick={() => setShowScan(true)}>📷 Scan</button>
          <button className="btn btn-ghost btn-sm" onClick={() => setShowPw(true)}>🔑 Password</button>
          <button className="btn btn-ghost btn-sm" onClick={doLogout}>⏻ Logout</button>
        </div>
      </nav>
      {showPw   && <ChangePasswordModal onClose={() => setShowPw(false)} />}
      {showScan && <ScanModal onClose={() => setShowScan(false)} />}
    </>
  );
}
